from fractions import Fraction
from pathlib import Path


def fmt(q):
    # Точний десятковий запис скінченного дробу без зайвих нулів у кінці
    k = 0
    while (10 ** k) % q.denominator:
        k += 1
    m = q.numerator * (10 ** k // q.denominator)
    sign = "-" if m < 0 else ""
    digits = str(abs(m)).rjust(k + 1, "0")
    ip, fp = digits[:len(digits) - k], digits[len(digits) - k:]
    fp = fp.rstrip("0")
    return sign + ip + ("." + fp if fp else "")


